	var cur BQSlotList = t
	for {
		c, ok := cur.(*ConcBQSlotBQSlotList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcBQSlotBQSlotList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concBQSlot list is not a BQSlot", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
